// Extract message data from Meta WhatsApp webhook payload
const webhookData = $input.first().json;
const body = webhookData.body || webhookData;

let phoneNumber = '';
let messageText = '';
let messageId = '';
let contactName = '';
let metaTimestamp = '';

if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const change = body.entry[0].changes[0];
  if (change.value && change.value.messages && change.value.messages[0]) {
    const msg = change.value.messages[0];
    phoneNumber = msg.from || '';
    messageId = msg.id || '';
    messageText = msg.text?.body || msg.button?.text || msg.interactive?.button_reply?.title || '';
    metaTimestamp = msg.timestamp || '';

    if (change.value.contacts && change.value.contacts[0]) {
      contactName = change.value.contacts[0].profile?.name || '';
    }
  }
}

// Skip status update webhooks (delivered, read) that have no message content
if (!phoneNumber || !messageText) {
  return [];
}

const sessionId = phoneNumber.replace(/[^0-9]/g, '');

return {
  json: {
    phoneNumber,
    sessionId,
    messageText,
    messageId,
    contactName,
    metaTimestamp,
    timestamp: new Date().toISOString()
  }
};

const systemPromptPart1 = `You are Layla, the heart of Horizon Africa — an authorised Telkom partner based in Durban that facilitates and manages the customer lifecycle for Telkom telecommunications services in South Africa. We only serve customers within South Africa.

## CRITICAL — WHO IS WHO
- **Telkom** is the ISP and network provider. Telkom provides the data connection, network infrastructure, speeds, and the telecommunications service. Customers are taking a Telkom service.
- **Horizon Africa** is NOT the ISP or network provider. Horizon Africa facilitates the customer lifecycle — sales, qualification, communication, follow-ups, onboarding, and support.
- Never say "Horizon Africa has fast/slow speeds" or "Horizon Africa's network". Say "Telkom's network" or "Telkom's fibre".
- **Telkom is our ONLY ISP partner.** Never reference other ISPs or suggest we service multiple ISPs.
- Customers take their telecommunications service from Telkom, not Horizon Africa.

## PERSONALITY
- Warm, welcoming, emotionally intelligent — match the customer's energy
- Curious — ask thoughtful questions, listen first
- Confident and clear — no guessing. If you don't know, say so honestly
- Kind, never sarcastic or defensive. Gentle humour, always professional
- Teach, don't lecture — explain technical topics simply
- Natural South African English, conversational, concise (3-4 sentences max unless listing packages)
- Maximum 1 emoji per message, used sparingly
- Never pushy. Use the customer's name once you know it
- Never break character. Never say "I'm an AI" or "as a language model"

## YOUR ROLE
1. Answer questions about Telkom Fibre packages using the PRODUCT CATALOG below
2. Qualify leads by asking about their internet needs
3. Recommend the right Telkom package
4. Collect lead information for the sales team
5. Identify hot leads ready to sign up
6. Schedule follow-ups when customers request them

## QUALIFICATION PROCESS
Step 1: "How many people will be using the internet at your place?" (1 Person | 2-4 People | 5+ People)
Step 2: "What do you mainly use the internet for?" (Email, Browsing, Netflix, YouTube, Gaming, Working from Home, CCTV, Smart Home, Business, Online School, Video Calls)
Step 3: Recommend a Telkom package based on their answers
Step 4: Collect details — **use the KNOWN CUSTOMER INFO section.** If we already have name, number, email, or address, do NOT ask again. Confirm it: "I have your number as [number] — is this still the best number?" Only ask for details we don't have.

## POST-PAID FIRST
Always prioritise post-paid (monthly contract) Telkom services first. Where the customer qualifies (credit assessment), guide them towards post-paid. Prepaid is only an alternative (customer doesn't qualify for credit, prefers no contract, or explicitly asks). Never position prepaid as the preferred option.

## OBJECTION HANDLING
When a customer raises an objection, pause qualification and address it first, then guide back.

**Price Too High:** Empathize, compare to mobile data spend, suggest cheaper Telkom package (20/10 at R345), ask one discovery question. Escalate if they want a discount or custom pricing.
**Comparing Providers:** Validate, offer to compare on speed/price/installation/terms. Highlight Telkom's network reliability and Horizon Africa's local support. Escalate only if they want detailed competitor comparisons.
**Need to Think:** Validate, summarise recommended package, tell them details are saved. Offer a follow-up reminder. Escalate only if they request a callback.
**Already Have Fibre:** Acknowledge, ask current provider/speed/satisfaction. Highlight Telkom benefits or migration assistance. Escalate if migration needs manual intervention.
**I'm Moving:** Acknowledge, ask new address, check Telkom fibre availability. If no fibre, suggest Telkom LTE/wireless.

## HUMAN HANDOVER — BUSINESS HOURS
Operating hours: **Monday to Friday, 08:00–17:00 SAST**.
- **During business hours:** "I'll connect you with our sales team right away — one of our consultants will assist you during our operating hours (Mon–Fri, 08:00–17:00)."
- **Outside business hours:** "I've noted that you'd like to speak to a consultant. Our team is available Mon–Fri, 08:00–17:00. A consultant will reach out to you first thing on the next business day."
- Never imply 24/7 or immediate availability outside business hours.
- The current time and business-hours status are in the CONTEXT section below.

## FOLLOW-UP SCHEDULING
When a customer asks to be contacted at a specific time ("contact me in two hours", "call me tomorrow at 3pm"):
1. Acknowledge warmly
2. Convert to an absolute timestamp using the current time in the CONTEXT section
3. Set the follow_up_at field in your JSON response to the ISO 8601 timestamp
4. Confirm with the customer: "I'll message you at [time]. Is that correct?"
5. Only set follow_up_at for explicit timed requests. For vague deferrals ("I'll think about it"), leave it null.

## KNOWLEDGE BASE

`;

const products = $('Fetch Products').all().map(i => i.json);
let catalogLines = ['### Product Catalog (Live from Database — Telkom Fibre Services)', ''];
products.forEach(p => {
  if (p.price_cents != null && p.price_cents > 0) {
    const priceStr = 'R' + (p.price_cents / 100).toFixed(p.price_cents % 100 === 0 ? 0 : 2);
    let line = '- ' + p.name + ' — ' + priceStr + '/' + p.billing_period;
    if (p.is_uncapped) line += ' (uncapped)';
    if (p.billing_type === 'post_paid') line += ' [post-paid]';
    catalogLines.push(line);
  } else {
    catalogLines.push('- ' + p.name + ' — pricing varies by area, consultant will confirm');
  }
});
catalogLines.push('');
catalogLines.push('- All packages are Telkom fibre services, uncapped — no FUP, no throttling, no data caps');
catalogLines.push('- Package availability depends on Telkom fibre infrastructure in the area');
catalogLines.push('- All current packages are post-paid. Prepaid fibre may be available in selected areas — mention only as an alternative');
catalogLines.push('');

const systemPromptPart2 = `
### Installation (Telkom)
- Existing fibre infrastructure: 3-5 business days. New installation: 5-7 business days
- An adult (18+) must be present. Installation carried out by Telkom; Horizon Africa coordinates scheduling

### Contracts
- Standard: 12 months. Month-to-month and prepaid available (T&Cs apply) — alternatives only
- Early cancellation allowed but termination fees may apply. Upgrades anytime; downgrades per contract terms

### Application Requirements
- Full Name, SA ID Number (passports accepted if visa covers contract — deposits apply), Contact Number, Physical Address, Email
- After approval: Bank Name, Account Number, Preferred Debit Order Date
- Credit assessment required for post-paid (conducted by Telkom)

### Deposits — IMPORTANT
- Deposits are managed and requested **directly by Telkom**
- Deposit payments are made **directly to Telkom**, not to Horizon Africa
- A deposit may be required if credit assessment doesn't meet Telkom's threshold (refundable)
- Horizon Africa guides the customer through the process — we do not collect or manage deposits

### Payment
- Debit orders mandatory for post-paid (Telkom billing). Prepaid paid before activation (directly to Telkom)
- Failed debit orders result in suspension; bank rejection fees passed on

### Technical (Telkom Network)
- All packages include ONT (Optical Network Terminal) — provided by Telkom
- Some packages include a Wi-Fi router — consultant will confirm
- Symmetrical fibre: upload = download (business, remote work, content creators)
- Asymmetrical fibre: faster download than upload (home use)
- All speeds and network performance are Telkom's — never attribute to Horizon Africa

### Support
- Telkom technical support: 10217 (Option 1: Technical, Option 2: Billing, Option 3: Customer Services)
- Sales Manager: khanyisg@telkom.co.za / 068 565 3272
- Customers can also contact Horizon Africa for guidance and lifecycle support

### LTE/Wireless
- Telkom LTE/Wireless available where fibre isn't. Pricing varies — consultant will confirm
- Do NOT quote fibre prices for LTE/Wireless. If asked, say "Let me get that info for you. I'll have one of our sales consultants reach out." and set needsEscalation to true

### Other
- Prepaid Telkom fibre available in selected areas — alternative only
- Business fibre solutions available — contact sales for custom Telkom packages
- ADSL to Fibre migration may qualify for free installation
- Relocation: check new address for Telkom fibre availability

### Out-of-Scope Products
- Horizon Africa facilitates Telkom services ONLY — we do not offer products outside the PRODUCT CATALOG
- We do NOT offer Starlink, satellite internet, mobile data plans, VoIP, or any product not in the catalog
- If asked about a product we don't offer: be honest, pivot to our Telkom offerings, highlight benefits (uncapped, low latency, local support, fast installation). Do NOT set needsEscalation unless they explicitly ask for a human

## RULES
- Always respond in the same language as the user (English or Afrikaans)
- Never invent information not in the knowledge base
- NEVER invent package names, speeds, or prices. Only quote from the PRODUCT CATALOG. If not listed, say "Let me get that info for you. I'll have one of our sales consultants reach out." and set needsEscalation to true.
- If user asks to speak to a human: use the HUMAN HANDOVER — BUSINESS HOURS section. Never imply 24/7 availability.
- Keep responses short and scannable. State speed and price clearly when recommending.
- Never ask more than one question at a time
- Greet new users: "Hi! Welcome to Horizon Africa — I'm Layla. How can I help you today?"
- If customer is outside South Africa, politely explain we only serve SA customers
- Always prioritise post-paid Telkom services. Prepaid only as an alternative.
- Never break character. You are Layla, always.

## RESPONSE FORMAT — IMPORTANT
You must respond as a JSON object:
{"reply": "<your message to the customer>", "follow_up_at": "<ISO 8601 timestamp if customer explicitly requested a timed follow-up, otherwise null>"}

The "reply" field is what gets sent on WhatsApp. The "follow_up_at" field schedules a follow-up — only set it when the customer explicitly asks to be contacted at a specific time. For vague deferrals, leave it null. Return ONLY the JSON object.`;

const systemPrompt = systemPromptPart1 + catalogLines.join('\n') + systemPromptPart2;

const msg = $('Extract Message').first().json;
const history = $('Fetch Conversation History').all().map(i => i.json);

let knownLead = null;
try {
  const leadData = $('Fetch Lead').first().json;
  if (leadData && leadData.length > 0) knownLead = leadData[0];
  else if (leadData && leadData.phone_number) knownLead = leadData;
} catch(e) {}

let knownInfoLines = [];
if (knownLead) {
  if (knownLead.full_name) knownInfoLines.push('- Name: ' + knownLead.full_name);
  if (knownLead.phone_number) knownInfoLines.push('- Contact number: ' + knownLead.phone_number);
  if (knownLead.email) knownInfoLines.push('- Email: ' + knownLead.email);
  if (knownLead.physical_address) knownInfoLines.push('- Address: ' + knownLead.physical_address);
  if (knownLead.recommended_package || knownLead.offered_package) knownInfoLines.push('- Previously recommended: ' + (knownLead.recommended_package || knownLead.offered_package));
}
if (!knownInfoLines.some(l => l.includes('Contact number'))) {
  knownInfoLines.push('- Contact number (from WhatsApp): ' + msg.phoneNumber);
}

const knownInfoSection = knownInfoLines.length > 0
  ? '\n## KNOWN CUSTOMER INFO (from database)\nDo NOT ask for any of these details again — confirm them if needed. Only ask for details NOT listed here.\n' + knownInfoLines.join('\n') + '\n'
  : '\n## KNOWN CUSTOMER INFO (from database)\n- Contact number (from WhatsApp): ' + msg.phoneNumber + '\nDo not ask for this number — confirm it if needed.\n';

const now = new Date();
const sastOffset = 2 * 60 * 60 * 1000;
const sastTime = new Date(now.getTime() + sastOffset);
const sastHour = sastTime.getUTCHours();
const sastDay = sastTime.getUTCDay();
const isBusinessHours = sastDay >= 1 && sastDay <= 5 && sastHour >= 8 && sastHour < 17;
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const businessHoursContext = '\n## CONTEXT — CURRENT TIME\nCurrent SAST: ' + sastTime.toISOString().replace('T',' ').substring(0,19) + ' (' + dayNames[sastDay] + ')\nWithin business hours (Mon-Fri 08:00-17:00): ' + (isBusinessHours ? 'YES' : 'NO') + '\nUse this for handover wording and converting relative follow-up times to absolute timestamps.\n';

const messages = [];
const fullSystemPrompt = systemPromptPart1 + catalogLines.join('\n') + knownInfoSection + businessHoursContext + systemPromptPart2;
messages.push({ role: 'system', content: fullSystemPrompt });

history.slice().reverse().forEach(h => {
  if (h.incoming_message) messages.push({ role: 'user', content: h.incoming_message });
  if (h.ai_response) messages.push({ role: 'assistant', content: h.ai_response });
});

let wasDelayed = false;
let delayMinutes = 0;
if (msg.metaTimestamp) {
  const metaTime = parseInt(msg.metaTimestamp) * 1000;
  delayMinutes = (Date.now() - metaTime) / 60000;
  if (delayMinutes > 5) wasDelayed = true;
}
if (history.length > 0) {
  const lastEntry = history[0];
  if (lastEntry.incoming_message && (!lastEntry.ai_response || lastEntry.ai_response === '')) wasDelayed = true;
}
if (wasDelayed) {
  const delayDesc = delayMinutes > 5 ? ' The customer waited approximately ' + Math.round(delayMinutes) + ' minutes.' : ' You missed the customer\'s previous message.';
  messages.push({ role: 'system', content: 'IMPORTANT: You were temporarily unavailable.' + delayDesc + ' Start your response with a brief, natural apology. Put it in the "reply" field of your JSON response.' });
}

messages.push({ role: 'user', content: msg.messageText });

return {
  json: {
    phoneNumber: msg.phoneNumber,
    sessionId: msg.sessionId,
    messageText: msg.messageText,
    messageId: msg.messageId,
    contactName: msg.contactName,
    timestamp: msg.timestamp,
    wasDelayed,
    knownLead: knownLead,
    isBusinessHours,
    openrouterRequest: {
      model: 'openai/gpt-5.6-sol',
      messages,
      temperature: 0.8,
      response_format: { type: 'json_object' }
    }
  }
};

// Parse OpenRouter response (JSON envelope) and score lead
const openrouterResult = $input.first().json;
const rawContent = openrouterResult.choices?.[0]?.message?.content || '';

const req = $('Build OpenRouter Request').first().json;

// --- Parse JSON envelope from AI response ---
let aiResponse = '';
let followUpAt = null;

try {
  const parsed = JSON.parse(rawContent);
  aiResponse = parsed.reply || parsed.response || parsed.message || '';
  followUpAt = parsed.follow_up_at || parsed.followUpAt || null;
} catch(e) {
  // Model didn't return valid JSON — use the raw content as the reply (fallback)
  // Try to extract reply from potential markdown code blocks
  const jsonMatch = rawContent.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[1].trim());
      aiResponse = parsed.reply || parsed.response || parsed.message || '';
      followUpAt = parsed.follow_up_at || parsed.followUpAt || null;
    } catch(e2) {
      aiResponse = rawContent;
    }
  } else {
    aiResponse = rawContent;
  }
}

if (!aiResponse) aiResponse = 'Sorry, I did not understand that. Could you rephrase?';

const messageLower = (req.messageText || '').toLowerCase();

let leadScore = 'COLD';

// Detect contact info in CURRENT USER MESSAGE only (not history, not AI response)
let hasPhone = /\b\d{10}\b|\b0\d{2}[\s-]?\d{3}[\s-]?\d{4}\b|\+\d{1,3}\s?\d{6,}/.test(messageLower);
let hasEmail = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(req.messageText || '');
let hasAddress = /\bstreet\b|\broad\b|\bavenue\b|\bdrive\b|\bplace\b|\bclose\b|\bblvd\b|\baddress\b|\bsuburb\b|\bunit\b|\bno\.?\s\d/i.test(messageLower);
let hasName = !!(req.contactName && req.contactName.length > 0);

let hasContactInfo = hasPhone || hasEmail;

// Sign-up intent keywords — check USER MESSAGE ONLY (not AI response)
const signUpIntent = /sign\s*up|install|apply|get\s*started|proceed|go\s*ahead|sounds\s*good|interested|let'?s\s*do\s*it|how\s*do\si\s*sign|ready\s*to\s*sign|let'?s\s*get\s*this|want\s*to\s*sign|go\s*for\s*it|sounds\s*perfect|that'?s\s*perfect/.test(messageLower);

// HOT: Current message shows explicit sign-up intent AND provides new contact info
// OR: Current message shows sign-up intent AND user already has name (from Meta profile)
if (signUpIntent && (hasContactInfo || hasAddress || hasName)) {
  leadScore = 'HOT';
} else if (hasContactInfo || hasAddress || (/price|cost|how\s*much|install|when\s*can|interested|package|sign\s*up/.test(messageLower) && hasName)) {
  leadScore = 'WARM';
} else if (/fibre|internet|broadband|wifi|data|lte|starlink/.test(messageLower)) {
  leadScore = 'WARM';
}

// --- Check accumulated contact info across full conversation ---
const history = $('Fetch Conversation History').all().map(i => i.json);
const allUserText = history.map(h => h.incoming_message || '').join(' ') + ' ' + (req.messageText || '');

let hasPhoneAccum = /\b\d{10}\b|\b0\d{2}[\s-]?\d{3}[\s-]?\d{4}\b|\+\d{1,3}\s?\d{6,}/.test(allUserText);
let hasEmailAccum = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(allUserText);
let hasAddressAccum = /\bstreet\b|\broad\b|\bavenue\b|\bdrive\b|\bplace\b|\bclose\b|\bblvd\b|\baddress\b|\bsuburb\b|\bunit\b|\bno\.?\s\d/i.test(allUserText);
let hasNameAccum = !!(req.contactName && req.contactName.length > 0);

// HOT: Customer has provided all key contact details across the conversation
if (hasNameAccum && hasPhoneAccum && hasEmailAccum && hasAddressAccum) {
  leadScore = 'HOT';
}

// --- Objection Detection ---
let objectionType = null;
const objectionPatterns = [
  { type: 'price_too_high', regex: /too expensive|can'?t afford|price is too high|out of my budget|paying less|fibre costs too much|not worth the money|don'?t want another monthly expense|more than i expected|too pricey|can'?t afford it/ },
  { type: 'comparing_providers', regex: /still comparing|looking around|want to compare|getting other quotes|waiting for another provider|haven'?t decided|shopping around|checking other|comparing options/ },
  { type: 'need_to_think', regex: /i'?ll think about|let me decide|discuss it with|discuss with my family|i'?ll get back to you|i'?ll let you know|not today|need to think|let me think|think about it/ },
  { type: 'already_have_fibre', regex: /already have fibre|with another provider|already connected|don'?t need fibre|my internet is working|already got fibre|have internet already|current provider/ },
  { type: 'moving', regex: /i'?m moving|relocating|new address|changing houses|moving next month|moving soon|moving to|relocation/ }
];
for (const p of objectionPatterns) { if (p.regex.test(messageLower)) { objectionType = p.type; break; } }

// --- Escalation Detection ---
let needsEscalation = false;

// 1) Check USER MESSAGE for explicit escalation requests
const escalationRegex = /discount|negotiate|custom pricing|callback|speak to a consultant|speak to a human|speak to someone|contract negotiation|can you call me|get a call|manager|supervisor|check.*availability|check.*coverage|is fibre available|check if.*available|coverage at|available at my|available at that|available at the/;
if (escalationRegex.test(messageLower)) { needsEscalation = true; }

// 2) Check AI RESPONSE for escalation trigger phrases
const aiResponseLower = (aiResponse || '').toLowerCase();
const aiEscalationRegex = /let me get that info|i'?ll have one of our sales consultants|sales consultant reach out|one of our consultants will|let me check with the team|i'?ll have a consultant|reach out to you with that info|reach out to you with more info|not listed in our|isn'?t listed in our|not in our catalog|isn'?t in our catalog/;
if (aiEscalationRegex.test(aiResponseLower)) { needsEscalation = true; }

// --- Follow-up Detection ---
// Primary: AI structured output (follow_up_at from JSON envelope)
let followUpRequested = false;
let followUpDate = null;

if (followUpAt) {
  // Validate the timestamp
  const parsedDate = new Date(followUpAt);
  if (!isNaN(parsedDate.getTime())) {
    followUpRequested = true;
    followUpDate = parsedDate.toISOString();
  }
}

// Fallback: regex-based detection for vague deferrals ("I'll think about it" etc.)
if (!followUpRequested) {
  const followUpRegex = /think about it|get back to you|let you know|let me decide|discuss it with|discuss with my family|not today|need to think|let me think/;
  if (followUpRegex.test(messageLower)) {
    followUpRequested = true;
    const d = new Date(); d.setDate(d.getDate() + 3);
    d.setHours(9, 0, 0, 0); // Default to 9am, 3 days from now
    followUpDate = d.toISOString();
  }
}

// Objection or escalation bumps COLD to WARM minimum
if ((objectionType || needsEscalation) && leadScore === 'COLD') { leadScore = 'WARM'; }

return {
  json: {
    phoneNumber: req.phoneNumber,
    sessionId: req.sessionId,
    contactName: req.contactName,
    incomingMessage: req.messageText,
    aiResponse: aiResponse,
    leadScore: leadScore,
    hasContactInfo: hasContactInfo,
    hasAddress: hasAddress,
    objectionType: objectionType,
    needsEscalation: needsEscalation,
    followUpRequested: followUpRequested,
    followUpDate: followUpDate,
    isBusinessHours: req.isBusinessHours,
    timestamp: req.timestamp
  }
};

const p = $('Process Response').first().json;
// Parse the AI response to extract just the reply text
let replyText = p.aiResponse;
try {
  const parsed = JSON.parse(p.aiResponse);
  if (parsed.reply) replyText = parsed.reply;
} catch (e) {
  // If it's not JSON, use the raw response
  replyText = p.aiResponse;
}
return { json: { messaging_product: 'whatsapp', to: p.phoneNumber, type: 'text', text: { body: replyText }, phoneNumber: p.phoneNumber, aiResponse: p.aiResponse, leadScore: p.leadScore, contactName: p.contactName, incomingMessage: p.incomingMessage, timestamp: p.timestamp } };

const p = $('Process Response').first().json;
const history = $('Fetch Conversation History').all().map(i => i.json);

// Build conversation summary
let convoSummary = '';
let allMessages = [];

// Add history messages
history.forEach((h, idx) => {
  if (h.incoming_message && h.ai_response) {
    allMessages.push({ role: 'Client', text: h.incoming_message, response: h.ai_response });
  }
});

// Add current message
allMessages.push({ role: 'Client', text: p.incomingMessage, response: p.aiResponse });

// Build readable conversation
convoSummary = allMessages.map((m, i) => 
  `<tr><td style="padding:8px;border-bottom:1px solid #eee;background:#f9f9f9;"><strong>Client:</strong> ${m.text}</td></tr>` +
  `<tr><td style="padding:8px;border-bottom:1px solid #eee;"><strong>Layla AI:</strong> ${m.response}</td></tr>`
).join('');

// Extract collected info from conversation
const allText = allMessages.map(m => m.text + ' ' + m.response).join(' ');
const emailMatch = allText.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
const phoneMatch = allText.match(/\b0\d{2}[\s-]?\d{3}[\s-]?\d{4}\b|\b\d{10}\b/);
const addressMatch = allText.match(/(?:\d+\s+)?(?:[A-Z][a-z]+\s)+(?:Street|Road|Avenue|Drive|Place|Close|Boulevard|Blvd|Suburb|Unit|No)/i);

// Detect package interest
let packageInterest = 'Not specifically mentioned';
const pkgMatch = allText.match(/(\d{2,3})\s*\s*mbps|(\d{2,3})\s*\s*mb/i);
if (pkgMatch) packageInterest = pkgMatch[0] + ' package';
const priceMatch = allText.match(/R(\d{3,4})/);

// Detect usage patterns
let usagePattern = 'General browsing';
if (/netflix|streaming|youtube/i.test(allText)) usagePattern = 'Streaming (Netflix, YouTube)';
if (/gaming/i.test(allText)) usagePattern += ', Gaming';
if (/work.*home|wfh|remote.*work/i.test(allText)) usagePattern += ', Working from home';
if (/browsing|email/i.test(allText)) usagePattern += ', Browsing';

// Build closing recommendations
let closingTips = [];
closingTips.push('Call the client within 15 minutes while interest is highest');
closingTips.push('Reference their specific needs: ' + usagePattern);
if (packageInterest !== 'Not specifically mentioned') {
  closingTips.push('Confirm availability of the ' + packageInterest + ' at their address');
}
closingTips.push('Have installation time slots ready to offer');
closingTips.push('Mention any current promotions or free installation offers');
if (priceMatch) {
  closingTips.push('Confirm pricing: R' + priceMatch[1] + '/month - be ready to offer a discount for upfront payment');
}
closingTips.push('If no answer, send a WhatsApp message referencing this conversation');

const htmlContent = `
<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto;">
  <div style="background: linear-gradient(135deg, #ff6b35, #f7931e); padding: 20px; border-radius: 10px 10px 0 0; text-align: center;">
    <h1 style="color: white; margin: 0;">🔥 HOT LEAD ALERT</h1>
    <p style="color: white; margin: 5px 0 0 0;">This lead is ready to convert — follow up immediately!</p>
