const items = $input.all();
// If conversation history is empty, pass through a placeholder so downstream nodes still execute
if (items.length === 0) {
  return [{ json: { phone_number: $('Extract Message').first().json.phoneNumber, incoming_message: null, ai_response: null, lead_score: null, timestamp: null, no_history: true } }];
}
return items;

const handover = $('Prepare Chatwoot Handover').first().json;
const phoneNumber = handover.phoneNumber;
const contactName = handover.contactName;
const email = handover.email;

const baseUrl = 'http://chatwoot-rails:3000/api/v1/accounts/1';
const headers = {
  'api_access_token': 'KpQFg9xPSDhYsADy7XZHhNjJ',
  'Content-Type': 'application/json'
};

// Search for existing contact by phone number - paginate through all results
let contactId = null;
const searchPhone = `+${phoneNumber}`;
let page = 1;

while (!contactId && page <= 10) {
  let searchResp;
  try {
    searchResp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}/contacts?search=${encodeURIComponent(phoneNumber)}&page=${page}`,
      headers,
      json: true,
      timeout: 10000
    });
  } catch (e) {
    break;
  }

  const contacts = searchResp.payload || [];
  if (contacts.length === 0) break;

  for (const c of contacts) {
    if (c.phone_number === searchPhone || c.phone_number === phoneNumber ||
        c.identifier === searchPhone || c.identifier === phoneNumber) {
      contactId = c.id;
      break;
    }
  }
  page++;
}

// If not found, create new contact
if (!contactId) {
  try {
    const createResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/contacts`,
      headers,
      body: {
        name: contactName,
        phone_number: searchPhone,
        email: email || null,
        identifier: searchPhone
      },
      json: true,
      timeout: 10000
    });
    // Chatwoot create response: { payload: { contact: { id: ... } } }
    contactId = createResp.payload?.contact?.id || createResp.id || createResp.payload?.id;
    if (!contactId) {
      throw new Error('Contact created but no ID found in response: ' + JSON.stringify(createResp).substring(0, 500));
    }
  } catch (e) {
    // Create failed - try searching again with broader terms
    page = 1;
    while (!contactId && page <= 10) {
      let searchResp;
      try {
        searchResp = await this.helpers.httpRequest({
          method: 'GET',
          url: `${baseUrl}/contacts?search=${encodeURIComponent(searchPhone)}&page=${page}`,
          headers,
          json: true,
          timeout: 10000
        });
      } catch (e2) {
        break;
      }
      const contacts = searchResp.payload || [];
      if (contacts.length === 0) break;
      for (const c of contacts) {
        if (c.phone_number === searchPhone || c.identifier === searchPhone) {
          contactId = c.id;
          break;
        }
      }
      page++;
    }
    if (!contactId) {
      throw new Error(`Failed to find or create contact: ${e.message}`);
    }
  }
}

return { json: { id: contactId, phoneNumber, contactName, email, inboxId: handover.inboxId } };
